 x=start('t1-04','The cycle workshop has two kinds of stop|骑行工坊：停用头盔，不等于全场停办','It is14:00. Settle the already-paid16:00 cycle workshop by16:00. Recall affected loan helmets, preserve safe maintenance bookings and offer each affected rider a usable accepted remedy. The riding group goes out16:00–16:20; non-riders start repairs16:00, riders start repairs after returning16:20. The tutor leads the ride, so get Ari’s actual first-bench cover rather than putting one teacher in two places.|现在14:00。16:00前处理已付费的骑行工坊，召回受影响借用头盔，保留安全维修课，给受影响骑手实际可用且接受的补救。骑行组16:00–16:20外出，不骑车的人16:00先修，骑行的人16:20回来再修。导师带骑，前一段维修台得落实Ari接班，不能把同一个老师排在两处。','Open manufacturer serial recall, physical helmet stock, paid booking requests, guardian thread, replacement delivery, tutor requirements, actual allocation/booking desks and outgoing instructions.|打开厂商序列召回、实物头盔库存、付费报名需求、监护人私信、替换配送、老师要求、实际分配预约台及待发指引。','precise',120)
 x.source('recall','Manufacturer’s scoped recall|厂商范围明确的召回',txt('recall-note','Only serials H8-01 and H8-02 of loan helmet batch H8 are recalled. H9-01 is not. H8 must be physically removed from the loan rack into locked return stock; do not dispose of privately owned visitor helmets or stop maintenance-only tuition.|只召回借用H8批的H8-01、H8-02，H9-01不在内。H8须从借用架实物转进锁闭退货库，不处理访客私有头盔，也不停止仅维修课程。'))
 x.source('stock','Actual serial/size stock|实际序列及尺寸库存',field('helmet-stock','Actual allocated helmets|实际分配头盔',{'H8-01':'rack','H8-02':'rack','H9-01':'rack','N-small':'not-arrived','N-large':'not-arrived'}),txt('fit-note','Rider Jun needs small, rider Farah large. Both affected riders are on site now for an advance equipment fitting. Sizes are part of booking fit, not guessed from age. N-small and N-large are certified workshop stock, H9-01 medium fits neither affected rider.|Jun需小号，Farah需大号，两位受影响骑手已在现场做课前器材适配，尺寸来自报名适配，不按年龄猜。N-small/N-large为合格工坊库存，H9-01中号都不合两人。'))
 x.source('bookings','Paid distinct bookings and accepted remedies|不同付费报名与接受的补救',dm('jun-dm','Jun is booked for supervised riding plus maintenance. I am his guardian. If a certified small replacement arrives, he can join; otherwise refund the riding portion30 and let him start his paid repairs at16:00. Please tell me privately, no child details in the group.|Jun已报指导骑行加维修。我是监护人，有合格小号替换就参加，否则退骑行部分30，让他16:00直接上已付的维修课。请私下告诉我，别在群里发孩子情况。','Jun guardian'),dm('farah-dm','I booked riding and maintenance. A large replacement is fine. If there is none, I want the same riding refund30 and keep maintenance. Do not convert me into a waiting list without asking.|我报了骑行加维修，大号替换可以。没有就退骑行30保留维修，不要不问就把我转候补。','Farah'),dm('lee-dm','My own helmet is not loan stock. I paid maintenance only and can still come at16:00.|我的头盔是自带的，不属借用库存。我只付维修课，16:00仍能来。','Lee'),field('booking-state','Actual paid workshop components|实际付费课程组成',{'Jun_riding':True,'Jun_maintenance':True,'Farah_riding':True,'Farah_maintenance':True,'Lee_maintenance':True,'Jun_helmet':'H8-01','Farah_helmet':'H8-02','Jun_refund':0,'Farah_refund':0}))
 x.contact('delivery','Actual replacement delivery|实际替换送达','delivery-dm','I can report exactly which replacement helmets have reached your receiving desk. An order confirmation is not arrival.|我能报究竟哪些替换头盔到了你们收货台，订单确认不算送达。','Supplier',('stock',))
 x.answer('delivery-dm','stock',('N-small and N-large have both physically arrived, intact, with certificates.|N-small与N-large都已实物到货，完好，证书齐。' if branch=='A' else 'Only N-large physically arrived. N-small remains at our warehouse and cannot get here by16:00.|只N-large实物到，N-small还在仓库，16:00前到不了。'),rid='stock-result',set={'helmet-stock':{'N-small':'receiving' if branch=='A' else 'not-arrived','N-large':'receiving'}})
 x.source('tutor','Tutor’s actual workshop conditions|老师实际课程条件',dm('tutor-dm','I lead the ride16:00–16:20, then join the repair bench. Ari is our qualified workshop mechanic and may cover the entrance bench for up to two non-riders16:00–16:20; get that shift accepted. Lee starts repairs16:00, and Jun does too if his riding is refunded. Riding participants come to repairs16:20. Crew may use the private booking aliases for teaching, not public child details.|我16:00–16:20带骑，回来再到维修台。Ari是本工坊合格技师，可以接16:00–16:20入口维修台、带最多两位不骑车的人，但要先跟对方把班定下。Lee16:00开始修，Jun退骑行的话也16:00修；骑行的人16:20回来再修。工作人员可在教学中用报名昵称，孩子的私事别公开。','Tutor'),field('fit-state','Actual individual helmet checks|实际个人头盔检查',{'Jun':False,'Farah':False}))
 x.source('outgoing','Existing public and individual instructions|原公开及个人指引',post('main','Everyone will get an H8 loan helmet and ride first at16:00.|大家16:00先领H8头盔骑车。'),post('queue-copy','H8 helmets checked safe for all workshop riders.|工坊所有骑手H8头盔已查安全。',status='draft'),old('old-maintenance','Maintenance-only visitors must join the opening ride too.|只修车的也得先参加开场骑行。'),field('queue-state','Actual queued announcement|实际队列通知',{'active':True,'sent':False}))
 desk(x,'recall-desk','Actual recalled-stock custody|实际召回库存保管','recall-desk','Move both identified H8 units into locked return stock together; other helmets remain in their existing ownership.|将两件识别出的H8一起移入锁闭退货库，其余头盔保留原归属。',{'quarantine':option('Quarantine both recalled H8 units|隔离两件被召回H8',set={'helmet-stock':{'H8-01':'locked-return','H8-02':'locked-return'}})})
 desk(x,'allocation','Actual individual replacement and fit desk|实际个人替换及适配台','allocation','Allocation checks actual receiving stock; fit check records a real fitting for the named rider and assigned serial. H9 medium is in stock but does not fit these bookings.|分配依据实收库存，适配检查针对具体人及所分序列实际进行。H9中号在库，但不合本题两位报名尺寸。',{'assign':option('Assign a received replacement|分配已收替换',schema={'rider':['Jun','Farah'],'serial':['N-small','N-large','H9-01']},parameter_record={'resource':'booking-state','field':'last_allocation'},param_variants=[dict(param_values={'rider':r,'serial':s},requires={'fields':{'helmet-stock':{s:'receiving' if s.startswith('N-') else 'rack'}}},set={'booking-state':{r+'_helmet':s},'helmet-stock':{s:r}}) for r in ['Jun','Farah'] for s in ['N-small','N-large','H9-01']]),'fit':option('Perform actual rider fit check|实际进行骑手适配检查',schema={'rider':['Jun','Farah']},param_variants=[dict(param_values={'rider':r},set={'fit-state':{r:True}}) for r in ['Jun','Farah']])})
 desk(x,'remedy','Actual paid component remedy desk|实际付费分项补救台','remedy','Keep accepted maintenance components. A riding refund removes that component and returns30 to its original payer; it does not refund or cancel another person’s maintenance. Existing DM choices authorise these conditional remedies.|保留已接受维修部分。退骑行会移除该部分并向原付款人退30，不退别人的维修。原私信选择已允许这些条件补救。',{'riding-refund':option('Return riding30 to the named payer|向指定付款人退骑行30',schema={'rider':['Jun','Farah']},param_variants=[dict(param_values={'rider':r},set={'booking-state':{r+'_riding':False,r+'_refund':30,r+'_helmet':None}}) for r in ['Jun','Farah']]),'cancel-all':option('Cancel all workshop components|取消全部工坊组成',set={'booking-state':{'Jun_riding':False,'Jun_maintenance':False,'Farah_riding':False,'Farah_maintenance':False,'Lee_maintenance':False}})})
 desk(x,'publisher','Actual outgoing queue control|实际待发队列控制','publisher','Stop the stale H8 safety job before15:00 release; release the corrected queue-copy only after editing it.|15:00发布前停掉旧H8安全通知，改queue-copy后再发。',{'pause':option('Pause stale queued announcement|暂停旧待发通知',set={'queue-state':{'active':False}}),'release':option('Release corrected current copy|发更正后的当前文案',set={'queue-state':{'sent':True}},patch={'queue-copy':{'status':'published'}})})
 x.c['lookups']['card/outgoing'].append(post('released-announcement','No announcement released yet.|尚未发出通知。',status='draft'))
 x.c['events'].append(dict(id='automatic-15-release',at=60,when={'fields':{'queue-state':{'active':True,'sent':False}}},copy=[{'from':'queue-copy','to':'released-announcement','attributes':['text']}],patch={'released-announcement':{'status':'published','published_at':60}},set={'queue-state':{'sent':True}}))
 x.c['operations']['publisher/release'].setdefault('copy',[]).append({'from':'queue-copy','to':'released-announcement','attributes':['text']})
 x.c['operations']['publisher/release'].setdefault('patch',{})['released-announcement']={'status':'published'}
 x.source('return','Supplier recall collection acceptance|供应商召回收回约定',dm('return-dm','Once H8 is locked out of loan circulation, submit its two serials to the collection desk. We then accept actual custody of both recalled units; the workshop keeps its H9 and replacements.|H8锁出借用流转后，把两序列交召回收回台，我们实际接回两件。工坊留H9和替换品。','Recall collector'),field('return-state','Actual recalled units received by supplier|供应商实际收到召回件',{'received':False}))
 desk(x,'collection','Actual H8 return pickup|实际H8召回收件','collection','Transfers the two locked H8 units into supplier custody with their serial record.|按序列把两件锁闭H8转到供应商保管。',{'accept':option('Supplier receives both recalled H8 units|供应商收回两件H8',requires={'fields':{'helmet-stock':{'H8-01':'locked-return','H8-02':'locked-return'}}},set={'helmet-stock':{'H8-01':'supplier','H8-02':'supplier'},'return-state':{'received':True}})})
 x.contact('bench-cover','Qualified Ari’s actual first repair-bench shift|合格技师Ari的前段维修台班','ari-dm','I can cover the entrance repair bench16:00–16:20 for up to two non-riders from the accepted workshop bookings. Send the concrete time and role; I have not taken this shift yet.|我可以16:00–16:20在入口维修台带已报名的、不骑车的学员，最多两位。把确切时间和带哪一台说清，我现在还没接下这班。','Ari',('cover',),schema={'start':['16:00'],'end':['16:20'],'bench':['entrance repair bench'],'group':['non-riders up to2']})
